"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[9876],{4692(e){e.exports=JSON.parse('{"title":"Polyfill\uc740 \ud544\uc694\ud560\ub54c\ub9cc.","date":"2023-09-27","coverUrl":null,"html":"<h2 data-notion-block-id=\\"ac2fc48b-0366-4e22-b549-ca8a10832fda\\" id=\\"ac2fc48b-0366-4e22-b549-ca8a10832fda\\">Polyfill\uc740 \ud544\uc694\ud560\ub54c\ub9cc.</h2><a href=\\"https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-6/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-6/</a><p data-notion-block-id=\\"1f1cf4be-220b-48c5-9e9f-331e4c361e81\\"><b>\uc2ec\uc724\uc12d</b>: \uc774 \uae00\uc740 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub294 \ucda9\ubd84\ud788 \ube60\ub974\uba70 \ud544\uc694\uc5c6\ub294 \ud3f4\ub9ac\ud544\uc774 \ub4e4\uc5b4\uac00 \uc18d\ub3c4\ub97c \ub2a6\ucd94\uace0 \uc788\ub2e4\ub97c \uc804\ub2ec\ud558\ub824\ub294 \uae00\uc785\ub2c8\ub2e4. \ud328\ud0a4\uc9c0\uc5d0 \ud3f4\ub9ac\ud544\uc774 \ub4e4\uc5b4\uc788\ub2e4\ub294 \ub0b4\uc6a9\uc778 \uae00\uc744 \uac00\uc838\uc628 \uc774\uc720\ub294 \ud328\ud0a4\uc9c0 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc11c\ube44\uc2a4\ub97c \ub9cc\ub4e4 \ub54c\uc5d0\ub3c4 \ud3f4\ub9ac\ud544\uc744 \ub9ce\uc774 \uc0ac\uc6a9\ud55c\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c \uc785\ub2c8\ub2e4. \ud3f4\ub9ac\ud544\uc744 \uc798 \uad00\ub9ac\ud558\uace0 \uc2f6\uace0, \ud1a0\uc2a4\uc758 \ud3f4\ub9ac\ud544 \uad00\ub9ac \uae00\uc744 \ud55c \ubc88 \uc0b4\ud3b4\ubcf4\uc2dc\uace0(\uc544\ubb34\ub798\ub3c4 \uc911\uac04 \uc11c\ube44\uc2a4\uc758 \uaddc\ubaa8\ub77c\ub3c4 \uc800\ub7f0 \uc11c\ube44\uc2a4\ub97c \uad6c\ucd95\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.) \uac04\ub2e8\ud558\uac8c <a href=\\"https://browsersl.ist/\\">browserlists</a>\ub97c \ud1b5\ud574 \ubcf8\uc778\uc758 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc9c0\uc6d0\ud558\ub824\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \uc815\ucc45\uc744 \ud1b5\ud574 \uc9c0\uc815\ud558\uace0 \uadf8\uc5d0 \ub9de\ub294 \ud3f4\ub9ac\ud544\ub9cc \uc801\uc6a9\ud558\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><p data-notion-block-id=\\"ffba8ffd-e1c1-4b0e-8178-e24b630f84c1\\"><b>\uae40\ub300\uad00</b>: \uc774\ub7f0 \uc885\uc18d\uc131 \uc81c\uac70\uc640 \uad00\ub828\ud574\uc11c \ub2e4\uc591\ud55c \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\ub294 \ud504\ub860\ud2b8\uc5d4\ub4dc\ub77c\ub294 \ud2b9\uc131\uc0c1 \uc774\ub7ec\ud55c \uc885\uc18d\uc131\uc740 \uc798 \ud310\ub2e8\ud574\uc11c \uc81c\uac70\ud574\uc57c\ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ucf54\ub4dc \uc720\uc9c0\ubcf4\uc218\ub97c \uc704\ud574\uc11c\ub294 \ub9ce\uc740 \uac83\uc744 \ub530\uc838\uc57c \ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4.<b> </b></p><p data-notion-block-id=\\"61029adf-4234-49bb-9dae-ce1e5ed18d49\\"><b>\ucd5c\uc6d0\ube48</b>: <a href=\\"https://toss.tech/article/smart-polyfills\\">\ud1a0\uc2a4\uc758 \ud3f4\ub9ac\ud544 \uc544\ud2f0\ud074</a>\uc5d0\uc11c\ub294 user-agent\ub97c \ud65c\uc6a9\ud55c \ud3f4\ub9ac\ud544 \uad00\ub9ac \ubc29\ubc95\uc5d0 \ub300\ud574 \ubc30\uc6b8 \uc218 \uc788\uc8e0. \ub108\ubb34 \ud3f4\ub9ac\ud544\uc744 \uc678\ubd80 \uc138\ud305\uc5d0\ub9cc \uc758\uc874\ud558\uae30\ubcf4\ub2e4, \uc8fc\uccb4\uc801\uc73c\ub85c \uad00\ub9ac\ud574\uc57c\ud55c\ub2e4\ub294 \uc88b\uc740 \uc778\uc2dd\uc744 \uc2ec\uc5b4\uc90d\ub2c8\ub2e4. \ud50c\ub7ec\uadf8\uc778\uacfc \uc0ac\uc804 \uc124\uc815\ub4e4\uc740 \uc815\ub9d0 \uc88b\uc9c0\ub9cc.. \ud55c\ubc88\ucbe4\uc740 \ubc97\uc5b4\ub0a0 \ud544\uc694\uac00 \uc788\uc5b4\ubcf4\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"ae0df4e8-130c-4844-a5b7-37952f5f4d67\\" id=\\"ae0df4e8-130c-4844-a5b7-37952f5f4d67\\">tsconfig.json\uc758 \ud568\uc815</h2><a href=\\"https://redd.one/blog/one-thing-nobody-explained-to-you-about-typescript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://redd.one/blog/one-thing-nobody-explained-to-you-about-typescript</a><p data-notion-block-id=\\"4e0010dd-506f-4f53-af2e-e3dffea575c7\\"><b>\uc2ec\uc724\uc12d</b>: TS\ub294 \uac15\ub825\ud55c \ub3c4\uad6c\uac00 \ub418\uae30\ub3c4 \ud558\uc9c0\ub9cc \ub54c\ub85c\ub294 \ud63c\ub780\uc744 \uac00\uc838\uc635\ub2c8\ub2e4. \uc774\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud574 \uc138\ud305\uacfc \ub514\ub809\ud1a0\ub9ac \ubd84\ub9ac\ub97c \ucca0\uc800\ud788 \ud558\ub77c\ub294 \uae00\uc785\ub2c8\ub2e4. TS\ub97c \uc785\ubb38\ud558\uae30\uc5d0\ub294 \uc88b\uc9c0\ub9cc \uc138\ud305\uc774 \uc27d\uc9c0\ub9cc\uc740 \uc54a\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \ub3c4\uad6c\uc640 \ucda9\ub3cc\ub3c4 \uc790\uc8fc \uc77c\uc5b4\ub098\uc8e0. \uc774 \uae00\uc740 \ucda9\ub3cc\uc744 \uc904\uc774\uae30 \uc704\ud574 <code>tsconfig.json</code>\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\uc5b4\uc57c \ud558\ub294\uc9c0 \uc54c\ub824\uc90d\ub2c8\ub2e4.</p><p data-notion-block-id=\\"a829c041-7c4c-43eb-9823-7c24c76ffe56\\"><b>\ucd5c\uc6d0\ube48</b>: \uc9c4\uc9dc \ub193\uce58\uace0 \uc788\ub358 \ubd80\ubd84\uc774\ub124\uc694\u2026 \u314b\u314b\u314b\u314b \ub8e8\ud2b8\uc5d0 tsconfig\ub97c \ub454\ub2e4\uace0 \ud574\uc11c \ub05d\ub098\ub294 \uac8c \uc544\ub2c8\ub77c\ub294 \ud6cc\ub96d\ud55c \uace0\ucc30\uc744 \uc5bb\uace0\uac11\ub2c8\ub2e4</p><p data-notion-block-id=\\"8bb0c04d-5df0-4731-9ec7-8802e09890c8\\"><b>\uae40\ub300\uad00</b>: \uace0\ub3c4\ub85c \ubc1c\ub2ec\ub41c \uae30\uc220\uc740 \ub9c8\ubc95\uacfc \uac19\ub2e4\ub294 \ub9d0\uc774 \uc788\ub4ef\uc774 \uc6b0\ub9ac\uac00 TS\ub97c \uc4f0\uba74\uc11c tsconfig\ub97c \uc2e0\uacbd\uc4f0\uc9c0 \uc54a\uace0 \ub9c8\ubc95\ucc98\ub7fc \uc4f0\uace0 \uc788\uc5c8\ub358 \uc800\ub97c \ub3cc\uc544\ubcf4\uac8c \ub418\ub124\uc694.</p><h2 data-notion-block-id=\\"c97396e6-5dc9-4a6c-9fe4-910a2f438627\\" id=\\"c97396e6-5dc9-4a6c-9fe4-910a2f438627\\">every\uc640 some\uc5d0 \ube48 \ubc30\uc5f4\uc744 \ub123\uc73c\uba74??</h2><a href=\\"https://humanwhocodes.com/blog/2023/09/javascript-wtf-why-does-every-return-true-for-empty-array/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://humanwhocodes.com/blog/2023/09/javascript-wtf-why-does-every-return-true-for-empty-array/</a><p data-notion-block-id=\\"5538f761-ae9f-4c5f-8c7a-b2a12910a7d8\\"><a href=\\"https://velog.io/@sehyunny/why-does-every-return-true-for-empty-array\\">(\ud55c\uad6d\uc5b4 \ubc88\uc5ed)</a></p><p data-notion-block-id=\\"8b492aa0-643c-419b-8c0a-bb8ac760e13e\\"><b>\ucd5c\uc6d0\ube48</b>: \u2018\ucef4\ud4e8\ud305\uc0ac\uace0\u2019\ub97c \ub530\ub77c \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\ub294 \uc124\uacc4\ub418\uc5c8\uace0, \uc774 \uacfc\uc815\uc5d0\uc11c \uc218\ub9ce\uc740 \uc218\ud559\uc801 \uc0ac\uace0\ub4e4\uc774 \ud3ec\ud568\ub429\ub2c8\ub2e4. \uc774\ubc88 \ub17c\uc81c\ub294 \uc218\ub7c9\ud654 <code>Quantifier</code> \ub97c \uae30\ubc18\uc73c\ub85c \ud569\ub2c8\ub2e4. \uc774\ub7f0 \uac1c\ub150\ub4e4\uc744 \uc870\uae08\uc529 \uc313\uc544\ub454\ub2e4\uba74, \ub2e4\ub978 \uc5b8\uc5b4\ub4e4\uc5d0\uc11c\ub3c4 \uacf5\ud1b5\uc801\uc73c\ub85c \uc4f0\uc774\ub294 - \ubcf4\ud1b5\uc740 \ubb34\uc758\uc2dd\uc801\uc77c \uc218 \uc788\ub294 \ubd80\ubd84\ub4e4\uc744 \uace0\ub824\ud574 \ucf54\ub4dc\ub97c \uc9e4 \uc218 \uc788\uac8c \ub420 \uac83 \uac19\uc544\uc694. \uc774\ub7f0 \uac1c\ub150\ub4e4\uc744 \ud655\uc7a5\ud55c \ubaa8\ub4c8\uc744 \ub9cc\ub4e4\ub54c \uc720\uc6a9\ud558\uaca0\uc5b4\uc694.</p><p data-notion-block-id=\\"c5e9e453-324c-4e14-863c-4dda15a8e90a\\"><b>\uae40\ub300\uad00: </b>\ucef4\ud4e8\ud130\uc758 \uc218\ud559\uc774\ub77c\ub294 \uac1c\ub150\uc774 \ub0b4\ud3ec\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubb34\uc2dc\ud574\uc11c\ub294 \uc548\ub418\ub294\uad6c\ub098\uc640 \uacf5\ud5c8\ucc38\uc774\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uac1c\ub150 \ubc30\uc6cc\uac11\ub2c8\ub2e4<b>. </b>\ucf5c\ubc31 \ud30c\ub77c\ubbf8\ud130 \ubb38\uc81c\uc5d0\uc11c \uc2dc\uc791\ub418\ub294 \uc758\ubb38\ubd80\ud130 \uc591\ud654\uc0ac \uac1c\ub150\uae4c\uc9c0\uc758 \uadfc\uac70\uae4c\uc9c0 \ubaa8\ub4e0 \ucf54\ub4dc\uc5d0\ub294 \uc758\ubbf8\uac00 \uc788\uad6c\ub098\ub3c4 \uc0c8\ub86d\uac8c \ubc30\uc6cc\uac11\ub2c8\ub2e4. \uae00\uc744 \ucc98\uc74c \uc77d\uc744 \ub54c \u201c\uc774\uac8c \uc65c true\uc9c0?\u201d\uc5d0 \ub300\ud55c \uc758\ubb38\uc744 \uac00\uc84c\ub294\ub370, \uc774 \uae00\uc744 \uc77d\uc73c\ub2c8 \uc798 \uc774\ud574\uac00 \ub418\uc5c8\uc2b5\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"6b761f8e-e536-41e7-a53a-76ac3c9db759\\" id=\\"6b761f8e-e536-41e7-a53a-76ac3c9db759\\">\uc2dc\uac01\uc801 \ud68c\uadc0 \ud14c\uc2a4\ud2b8 \uc2dc\uc791\ud558\uae30</h2><a href=\\"https://docusaurus.io/blog/upgrading-frontend-dependencies-with-confidence-using-visual-regression-testing\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://docusaurus.io/blog/upgrading-frontend-dependencies-with-confidence-using-visual-regression-testing</a><p data-notion-block-id=\\"8dbefda9-8ec4-4438-a5f3-30558a578a42\\"><b>\uc2ec\uc724\uc12d</b>: \uc2dc\uac01\uc801 \ud68c\uadc0 \ud14c\uc2a4\ud2b8\ub97c \ud558\ub294 \ubc29\ubc95\uacfc \uc8fc\uc758\ud560 \uc810\uc744 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. UI\uc758 1px\uc774 \ubc14\ub00c\ub294\uc9c0 \uc548 \ubc14\ub00c\ub294\uc9c0\ub294 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4dc\ub294 \uc785\uc7a5\uc5d0\uc11c \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4. \uc2dc\uac01\uc801 \ud68c\uadc0 \ud14c\uc2a4\ud2b8\ub97c \ub9ce\uc774 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc9c0\ub9cc \uc124\uc815 \ub418\uace0 \ub098\uc11c\ub294 \uac15\ub825\ud55c QA \ub3c4\uc6b0\ubbf8\uac00 \ub420 \uac83\uc785\ub2c8\ub2e4.(\ubaa8\ub4e0 \ud14c\uc2a4\ud2b8\uac00 \uadf8\ub807\uc9c0\ub9cc\uc694). \ud558\uc9c0\ub9cc E2E \ud14c\uc2a4\ud2b8\uc778\ub9cc\ud07c \uc791\uc131\ud558\ub294\ub370 \ub9e4\uc6b0 \ub9ce\uc740 \uc2dc\uac04\uc774 \ub4dc\ub294 \uac83\uc740 \uc778\uc9c0\ud558\uace0 \uc801\uc6a9\ud574\uc57c \ud560 \uac83 \uac19\ub124\uc694 \ud83d\ude03\uc2e4\ubb34\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud560\uc9c0 \uac71\uc815\uc778 \ubd84\ub4e4\uc740 if kakao 2020\uc758 <a href=\\"https://elseif.kakao.com/2020/session/96\\">UI \ud14c\uc2a4\ud2b8\ub97c \uc704\ud55c \uc5ec\uc815</a>\uc744 \ubcf4\uc2dc\uba74 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \uac04\ub2e8\ud55c \uc801\uc6a9\uae30\ub97c \ubcf4\uc2dc\ub824\uba74 \uce74\uce74\uc624\uc5d4\ud130\ud504\ub77c\uc774\uc988\uc758 <a href=\\"https://fe-developers.kakaoent.com/2023/230816-backstopjs-vrt2/\\">BackdropJS \uc801\uc6a9\uae30</a>, \ub2e4\ub978 \ud14c\uc2a4\ud2b8 \ubc29\ubc95\uc744 \ubcf4\uace0 \uc2f6\uc73c\uc2e0 \ubd84\ub4e4\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/6506fa3a74f16300015a4c33\\">\uc774 \uae00</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><p data-notion-block-id=\\"2126da3a-82f3-456c-a420-0c17b5c9ccec\\"><b>\uae40\ub300\uad00</b>: \uc2e4\uc81c \ud604\uc5c5\uc5d0\uc11c \uc0dd\uac01\ud588\uc744 \ub54c QA \uacfc\uc815\uc5d0\uc11c \ubc1c\uacac\ub418\uc9c0 \uc54a\ub358 \uc5d0\ub7ec\ub4e4\uc5d0 \ub300\ud574\uc11c \uc27d\uace0 \uac04\ud3b8\ud558\uac8c \ud560 \uc218 \uc788\ub2e4\ub294 \ud070 \uc7a5\uc810\uc744 \uac16\uace0 \uc788\ub294 \ud14c\uc2a4\ud2b8\ub77c\ub294 \uac83\uc744 \uc0c8\ub86d\uac8c \uc54c\uc558\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \ubcf8\uc778\uc774 \ud070 \uc6f9\uc744 \uad00\ub9ac\ud55c\ub2e4\uba74, \uc801\uc6a9\ud558\uc5ec QA\uc5d0 \uc18c\ube44\ub418\ub294 \uc2dc\uac04\uc744 \uc808\uac10\ud560 \uc218 \uc788\uc9c0 \uc54a\uc744\uae4c \uc0dd\uac01\uc744 \ub4e4\uac8c\ud558\ub294 \uc88b\uc740 \uae00\uc774\uc5c8\uc2b5\ub2c8\ub2e4. </p><h1 data-notion-block-id=\\"856bd29e-bffc-445e-87da-d9671a1f1e7f\\">Infcon 2023</h1><h2 data-notion-block-id=\\"bad6da1b-87bb-4532-8a32-bf5e10a301a2\\" id=\\"bad6da1b-87bb-4532-8a32-bf5e10a301a2\\">Streaming SSR\ub85c \uc624\uae30\uae4c\uc9c0\uc758 \uc5ec\uc815</h2><a href=\\"https://youtu.be/hPyyFu3lrEg?si=EDANXLbWuLNWokzc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://youtu.be/hPyyFu3lrEg?si=EDANXLbWuLNWokzc</a><p data-notion-block-id=\\"6dfd5376-9395-4c84-b123-e3530197a231\\"><b>\uc2ec\uc724\uc12d</b>: \uc694\uc998 \uc0c8\ub85c \ub4f1\uc7a5\ud558\ub294 \uae30\uc220\ub4e4\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ubb54\uc9c0 \ubaa8\ub97c \uac83\uc774\uc9c0\ub9cc \uc11c\ubc84\uc0ac\uc774\ub4dc\uc640 \uad00\ub828\ub41c \uac83\ub4e4\uc774 \ub9ce\uc774 \ub098\uc635\ub2c8\ub2e4.\uadf8 \uc911 \ud558\ub098\uac00 \uc774\ubc88 \ubc1c\ud45c\uc758 \uc911\uc2ec\uc774 \ub418\ub294 Streaming SSR\uc785\ub2c8\ub2e4. \ubcf4\ud1b5\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud1b5\ud574 \uc0ac\uc6a9\ud558\uae30 \ub54c\ubb38\uc5d0 \uc2e0\uacbd \uc4f8 \uc77c\uc774 \uc801\uc9c0\ub9cc \uc774\ub7ec\ud55c \uac1c\ub150\uc774 \uc815\ud655\ud788 \uc801\uc6a9\ub418\ub294\uc9c0 \ubcf4\uae30 \uc88b\uc740 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \ub354 \ub9ce\uc740 SSR \ubc29\uc2dd\uacfc SSR\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud558\uace0\uc790 \ud558\uc600\ub294\uc9c0 \ud655\uc778\ud558\ub824\uba74 patterns.dev\ub098 <a href=\\"https://dev.to/this-is-learning/why-efficient-hydration-in-javascript-frameworks-is-so-challenging-1ca3\\">\uc774 \uae00</a>\uc744 \ubd10\uc8fc\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4 \ud83d\ude03 </p><p data-notion-block-id=\\"62360505-8e70-41ad-bea9-d364ecc2f815\\"><b>\ucd5c\uc6d0\ube48:</b> CSR\uacfc SSR\uc5d0 \ub300\ud55c \uae30\ucd08\ub97c \uc798 \uc124\uba85\ud574\uc8fc\uc168\ub124\uc694. \uc608\uc2dc\ub4e4\ub85c \ud558\uc5ec\uae08 \uac01 \ubc29\uc2dd\uc758 \uc7a5\ub2e8\uc810\uc744 \uc368\ubcf4\uc9c0 \uc54a\uc558\ub354\ub77c\ub3c4 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\uc744 \uac83 \uac19\uc544\uc694.</p><h2 data-notion-block-id=\\"bc1624d7-c6b1-46f4-b25c-b805a0045971\\" id=\\"bc1624d7-c6b1-46f4-b25c-b805a0045971\\">\uac1c\ubc1c\uc790\ub85c \ub098\uc544\uac00\uae30</h2><a href=\\"https://youtu.be/JeXE5DeQ6nU?si=QNhr37kPwtlgtx38\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://youtu.be/JeXE5DeQ6nU?si=QNhr37kPwtlgtx38</a><p data-notion-block-id=\\"20d1c6d8-647c-4f12-a360-574277bbdaab\\"><b>\uc2ec\uc724\uc12d</b>: \uc774 \ubc1c\ud45c\ub294 \uae30\uc220 \ubc1c\ud45c\ub77c\uae30\ubcf4\ub2e4\ub294 \uc0b6\uc758 \ubc29\ud5a5\uc744 \uc783\uc5c8\uc744 \ub54c \ubcf4\uae30 \uc88b\uc740 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c \uc0dd\uac01\ud558\uace0 \ucd94\ucc9c\ub4dc\ub9ac\ub294 \uac83\uc740 \uc774\ub7f0 \ucee4\ub9ac\uc5b4\ub97c \uc774\uc5b4\ub098\uac00\ub294 \uac83\ub3c4 \uc88b\uc9c0\ub9cc \ubc88\uc544\uc6c3\uc774 \uc624\uc9c0 \uc54a\uac8c \uc0b6\uc758 \ubc29\ud5a5\uc744 \uc870\uae08\uc529 \ub098\uc544\uac00\ub294 \uac83\uc774 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc774 \ubc1c\ud45c\uc5d0\uc11c \ub9d0\ud558\ub4ef\uc774 \uc815\ub2f5\uc740 \uc5c6\uace0, \ubb50\ub4e0\uc9c0 \uadf9\ub2e8\uc801\uc73c\ub85c \uac00\uba74 \uc88b\uc9c0 \uc54a\ub2e4\ub294 \uac83\uc744 \ud56d\uc0c1 \uba85\uc2ec\ud558\uace0 \uc798 \uc26c\uace0 \uc798 \uacf5\ubd80\ud558\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><p data-notion-block-id=\\"33433a2c-da84-4601-adb5-fc4a4278a12d\\"><b>\ucd5c\uc6d0\ube48</b>: \uc6f9 \ud2b9\ud654, \uc81c\ud488 \ud2b9\ud654, \uc6b4\uc601 \ud2b9\ud654 \uc138 \uac00\uc9c0\ub85c \ud504\ub860\ud2b8\uc5d4\ub4dc \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1\uc744 \ubd84\ub958\ud55c \ubd80\ubd84\uc774 \ub9e4\uc6b0 \uc778\uc0c1\uc801\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uac01 \ubd84\uc57c\uc5d0 \ub300\ud55c \uc124\uba85\uc744 \uc77d\ub2e4\ubcf4\ub2c8 \uac00\uc2b4\uc774 \ub6f0\ub124\uc694. (\uac1c\uc778\uc801\uc73c\ub85c \uc81c\ud488 \ud2b9\ud654\ucabd\uc774 \ub04c\ub9bd\ub2c8\ub2e4) \ubc1c\ud45c <a href=\\"https://steady-study.super.site/frontend-engineer-career-roadmap\\">\ubcf8\ubb38</a>\uc5d0 \ud568\uaed8 \ucca8\ubd80\ub41c \uae00\ub4e4\ub3c4 \uc88b\uc740 \ub0b4\uc6a9\ub4e4\uc774 \ub9ce\uc73c\ub2c8 \ud55c\ubc88\uc529 \uc77d\uc5b4\ubcf4\uba74 \ub3c4\uc6c0\uc774 \ub420 \uac83 \uac19\uc544\uc694.</p><h2 data-notion-block-id=\\"07bb6093-3ee6-4900-8c14-e7db979bb76e\\" id=\\"07bb6093-3ee6-4900-8c14-e7db979bb76e\\">\uc6f9\ubdf0\ub97c \ud1b5\ud574 \uc571 \ub9cc\ub4e4\uae30</h2><a href=\\"https://youtu.be/hsh8BS7gyrY?si=SDpcTUvjqYe1o1_s\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://youtu.be/hsh8BS7gyrY?si=SDpcTUvjqYe1o1_s</a><p data-notion-block-id=\\"bff4cf0d-fd72-4f25-9787-e62be93264d0\\"><b>\uc2ec\uc724\uc12d</b>: \uc6f9\ubdf0\ub97c \uac00\uc9c0\uace0 \uc571\uc744 \uac1c\ubc1c\ud558\ub294 \ud68c\uc0ac\ub294 \ub9ce\uc9c0\ub9cc \uc5b4\ub5bb\uac8c \uc6f9\ubdf0\ub97c \uac00\uc9c0\uace0 \uc571\uc744 \ub9cc\ub4dc\ub294\uc9c0\ub294 \uac00\ub974\uccd0\uc8fc\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \ubc1c\ud45c\uc5d0\uc11c\ub294 RN + React-navigation\ub97c \ud1b5\ud574\uc11c \uc571\uc744 \uad6c\ud604\ud558\uace0 Next.js\ub85c \uc6f9\ubdf0\uc758 \uc6f9\uc744 \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uadfc\ub9c8\ucf13\uc5d0\uc11c \ub9cc\ub4e0 stackflow\ub77c\ub294 \uc88b\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub3c4 \uc788\uc73c\ub2c8 \uc0ac\uc6a9\ud574\ubcf4\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc744 \uac83\uc785\ub2c8\ub2e4. RN\uc758 \uc7a5\uc810\uc740 \ub2e4\ub978 \ud06c\ub85c\uc2a4 \ud50c\ub7ab\ud3fc \ub77c\uc774\ube0c\ub7ec\ub9ac\ubcf4\ub2e4 \uc131\uc219\ud558\ub2e4\ub294 \uc810\uc774\uc9c0\ub9cc \uc131\uc219\ud55c \uc0dd\ud0dc\uacc4\uac00 \ucee4\ubba4\ub2c8\ud2f0 \uc911\uc2ec\uc778\uac83\ub3c4 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4. \ud328\ud0a4\uc9c0\ub97c \ub9cc\ub4e4\ub358 \uc0ac\ub78c\uc774 \ub5a0\ub098\uba74 \uc9c1\uc811 \uace0\uccd0\uc57c \ud560 \uc218\ub3c4 \uc788\uace0, RN\uc744 Expo\ub97c \ud1b5\ud574\uc11c \uac1c\ubc1c\ud558\uac8c \ub418\uba74 \ube60\ub974\uac8c \uac1c\ubc1c\ud560 \uc218\ub294 \uc788\uc9c0\ub9cc, \uc5ed\uc2dc \uad00\ub9ac \ud3ec\uc778\ud2b8\uac00 \ub298\uc5b4\ub0a0 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c WebView\ub294 \ub290\ub9ac\uae30 \ub54c\ubb38\uc5d0, \uac00\ub2a5\ud558\uba74 \uc571\uc758 \uccab \ud654\uba74\uc740 \ub124\uc774\ud2f0\ube0c\uc5d0 \uac00\uae5d\uac8c \ub9cc\ub4dc\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"f2c0bb46-ad8b-490d-a10e-a9836fb5fcce\\"><b>\ucd5c\uc6d0\ube48</b>: \uc6f9\ubdf0\uc758 \uae30\ucd08 \uc124\uba85\ub4e4\uc744 \uc54c\uc544\uac00\uae30 \uc88b\uc740 \uac15\uc758\ub124\uc694. \uc6f9\uc5d0\uc11c\ub294 \ube0c\ub77c\uc6b0\uc800\uac00 \uad00\ub9ac\ud574\uc8fc\ub358 \ud788\uc2a4\ud1a0\ub9ac\ub97c, \uc6f9\ubdf0\uc5d0\uc11c\ub294 \uc2a4\ud06c\ub9b0 \uc2a4\ud0dd\uc73c\ub85c \ubaa8\uc544 \uad00\ub9ac\ud55c\ub2e4\ub358\uc9c0, \uc774\ub97c \uc704\ud55c \ub124\ube44\uac8c\uc774\uc158\uc740 \uc5b4\ub5a0\ud55c \uad6c\uc870\ub85c \ub3d9\uc791\ud558\ub294\uc9c0 \ub4f1\ub4f1.. \uc6f9\ubdf0\ub97c \uad00\ub9ac\ud560 \ub550 \uc774\ub7ec\ud55c \uc2a4\ud06c\ub9b0 \uc2a4\ud0dd\uc744 \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud558\ub294\uc9c0\uac00 \ucc38 \uc911\uc694\ud55c\ub370\uc694,\ud68c\uc6d0\uac00\uc785 \ud37c\ub110\uc744 \uc9c0\ub098 \ud68c\uc6d0\uac00\uc785\uc744 \uc644\ub8cc\ud588\uc744 \ub54c \uc313\uc5ec\uc788\ub294 \uc2a4\ud06c\ub9b0 \uc2a4\ud0dd\uc744 \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud560 \uc9c0 - \uc678\ubd80 \uc11c\ube44\uc2a4\uc758 \ud50c\ub85c\uc6b0\ub97c \uc9c0\ub09c \uacbd\uc6b0\uc5d4? \ucc98\ub7fc UX\ub97c \uace0\ub824\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\ub4e4\uc774 \ub9ce\uc73c\ub2c8 \uc774\ub7ec\ud55c \uc810\ub4e4\uc744 \uace0\ub824\ud560 \uc218 \uc788\ub3c4\ub85d \ucd08\ubc18 \uc124\uacc4\ub97c \ud574\ub450\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud574\uc694. \uc571\uc5d0\uc11c \uc0ac\uc6a9\uac00\ub2a5\ud55c \ub525\ub9c1\ud06c, \uc6d0\ub9c1\ud06c\uc640 \uac19\uc740 \uae30\ub2a5\ub4e4\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\uace0\uc694!</p><p data-notion-block-id=\\"71b839e6-1708-42fd-a097-0b6814ee0e73\\"></p>"}')}}]);